body.script:
    const THEME_KEY = 'jumper-junction_theme';
    const SUPABASE_URL = 'https://wbriqxebdkuqbtcvxtgv.supabase.co';
    const SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6IndicmlxeGViZGt1cWJ0Y3Z4dGd2Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzYyNTA4MTksImV4cCI6MjA5MTgyNjgxOX0._e1mILmLqzbAfgSsAGWzAez5v6Z7RHNR564O4yfJFN0';
    const supabaseClient = supabase.createClient(SUPABASE_URL, SUPABASE_KEY);

    function applyTheme(theme) {
      const resolved = theme === 'light' ? 'light' : 'dark';
      document.body.dataset.theme = resolved;
      localStorage.setItem(THEME_KEY, resolved);
    }
    applyTheme(localStorage.getItem(THEME_KEY) || 'dark');

    function setVerifyStatus(msg, tone) {
      const el = document.getElementById('verify-status');
      el.textContent = msg;
      el.style.color = tone === 'error' ? 'var(--red)' : tone === 'success' ? 'var(--green)' : 'var(--muted)';
    }

    function getPostLoginTarget(defaultTarget = '/') {
      const target = sessionStorage.getItem('jj_post_login_target');
      if (target) {
        sessionStorage.removeItem('jj_post_login_target');
        return target;
      }
      return defaultTarget;
    }

    let pendingEmail = sessionStorage.getItem('jj_pending_signup_email') || '';

    async function initVerify() {
      const hashParams = new URLSearchParams(location.hash.replace(/^#/, ''));
      const type = hashParams.get('type');

      if (type === 'signup') {
        const { data: { session } } = await supabaseClient.auth.getSession();
        if (session) {
          setVerifyStatus('Email confirmed. Redirecting...', 'success');
          setTimeout(() => location.href = getPostLoginTarget('/'), 800);
          return;
        }
      }

      if (!pendingEmail) {
        setVerifyStatus('Missing signup email. Please start from Create Account.', 'error');
        return;
      }
      document.getElementById('verify-message').textContent = `Enter the 6-digit code sent to ${pendingEmail}.`;
    }

    async function handleVerify() {
      if (!pendingEmail) return;
      const token = document.getElementById('otp').value.trim();
      if (token.length !== 6) return setVerifyStatus('Enter a valid 6-digit code.', 'error');
      setVerifyStatus('Verifying...', 'muted');
      const { error } = await supabaseClient.auth.verifyOtp({
        email: pendingEmail,
        token,
        type: 'signup'
      });
      if (error) return setVerifyStatus(error.message, 'error');
      setVerifyStatus('Verified. Redirecting...', 'success');
      setTimeout(() => location.href = getPostLoginTarget('/'), 800);
    }

    async function resendCode() {
      if (!pendingEmail) return;
      setVerifyStatus('Resending code...', 'muted');
      const { error } = await supabaseClient.auth.resend({
        type: 'signup',
        email: pendingEmail
      });
      if (error) return setVerifyStatus(error.message, 'error');
      setVerifyStatus('Code resent. Check your inbox.', 'success');
    }

    initVerify();
